fn to_lowercase(s: &Vec<char>) -> Vec<char> {
    let mut result = Vec::with_capacity(s.len());
    
    for &c in s {
        if ('A'..='Z').contains(&c) {
            // Convert to lowercase by adding 32 to the ASCII code point
            let lower_char = ((c as u8) + 32) as char;
            result.push(lower_char);
        } else {
            result.push(c);
        }
    }
    
    result
}